method count_upper(s: string) returns (count: int)
    requires s != null
    ensures count >= 0
    ensures count == CountUpperVowels(s)

    // Helper function to count uppercase vowels at even indices
    function CountUpperVowels(s: string): int
        requires s != null
        ensures Result >= 0
    {
        var c := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= i <= s.Length
            invariant c >= 0
        {
            if i % 2 == 0 && (s[i] == 'A' || s[i] == 'E' || s[i] == 'I' || s[i] == 'O' || s[i] == 'U') {
                c := c + 1;
            }
            i := i + 1;
        }
        return c;
    }
```

